INSERT INTO fund_report_vector (fund_code, manager_name, report_quarter, section_title, content) VALUES ('005827', '张坤', '2024Q2', '投资策略与运作分析', '在报告期内，本基金维持了对商业模式优秀、具备极强自由现金流产生能力与高资本回报率企业的核心配置。我们深信，时间是优秀企业的朋友，在消费和互联网优质资产估值深度回调后，龙头企业的股东回报率、分红与回购力度显著提升，具备强劲的长期复利价值。');
INSERT INTO fund_report_vector (fund_code, manager_name, report_quarter, section_title, content) VALUES ('003095', '葛兰', '2024Q2', '投资策略与运作分析', '从行业长期基本面来看，我国医药生物行业的创新升级与老龄化刚性需求依然具备长期确定性。二季度我们保持了创新药、医疗器械与CXO龙头的配置，重点聚焦具备全球化商业化潜力与真创新的优质企业。');
